import { cookies } from 'next/headers';
import { getRequestConfig } from 'next-intl/server';
import { defaultLocale, isLocale, LOCALE_COOKIE } from './config';

export default getRequestConfig(async () => {
  const store = await cookies();
  const fromCookie = store.get(LOCALE_COOKIE)?.value;
  const locale = isLocale(fromCookie) ? fromCookie : defaultLocale;
  // messages/runtime/* are generated by scripts/sync-messages.ts: un-reviewed (TODO) strings are already English.
  // They are precompiled at build time (next.config.ts) so the ICU parser stays out of the client bundle.
  const messages = (await import(`../messages/runtime/${locale}.json`)).default;
  return { locale, messages, timeZone: 'Africa/Johannesburg' };
});
